package com.costeo3d.infrastructure.persistence.dao;

import java.util.List;
import java.util.Optional;

import com.costeo3d.domain.model.Material;


public interface MaterialDao {

    // Returns a new Material instance with the ID generated by MySQL.
    Material insert(Material material);

    Optional<Material> findById(int id);

    // Includes active and inactive materials.
    List<Material> findAll();

    // Returns false if no material exists with the given ID.
    boolean update(Material material);
}
